fn cut_word(w: Str, width: Int) -> List[Str] {
  if w.len() <= width {
    return [w]
  }
  var out: List[Str] = []
  var start = 0
  while start < w.len() {
    out = out.push(w.slice(start, (start + width).min(w.len())))
    start = start + width
  }
  return out
}

pub fn wrap(text: Str, width: Int) -> List[Str] {
  let words = text.split(" ").filter(fn(w) => not (w.is_empty()))
  let pieces = words.flat_map(fn(w) => cut_word(w, width))
  var lines: List[Str] = []
  var cur = ""
  for p in pieces {
    if cur == "" {
      cur = p
    } else if cur.len() + 1 + p.len() <= width {
      cur = cur + " " + p
    } else {
      lines = lines.push(cur)
      cur = p
    }
  }
  if cur != "" {
    lines = lines.push(cur)
  }
  return lines
}
